package org.l2jmobius.gameserver.managers;
import java.io.*;import java.lang.classfile.*;import java.lang.constant.*;import java.lang.invoke.MethodHandles;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;
import org.w3c.dom.*;
import org.l2jmobius.gameserver.data.holders.AccessLevel;import org.l2jmobius.gameserver.entity.*;import org.l2jmobius.gameserver.entity.actor.*;import org.l2jmobius.gameserver.entity.actor.holders.creature.EffectList;import org.l2jmobius.gameserver.handler.EffectHandler;import org.l2jmobius.gameserver.mechanics.effects.*;import org.l2jmobius.gameserver.mechanics.skill.*;import org.l2jmobius.gameserver.mechanics.skill.enums.SkillFinishType;import org.l2jmobius.gameserver.mechanics.variables.PlayerVariables;import org.l2jmobius.gameserver.util.*;
import static java.lang.constant.ConstantDescs.*;

/** Настоящие Policy/State и Native GM/ACL/переменные; запись, пакеты и снятие эффекта контролируются. */
public class PlayingGmStateCheck {
 static sun.misc.Unsafe u;static Class<?> actorType;static int checks,nextId=100;static boolean enabled,defaultMode;static Skill gmSkill,hide,invul,ordinary;
 static final Map<Player,Actor> ACTORS=new IdentityHashMap<>();static final Map<Integer,Map<String,String>> DISK=new HashMap<>();
 static final class Actor {ControlledVariables variables;int broadcasts,weightRefresh,invisibleChanges;Set<Integer> removed=new HashSet<>();}
 public static class ControlledVariables extends PlayerVariables {
  int character,saves;boolean fail;
  ControlledVariables(int id){super(id);character=id;for(var e:DISK.getOrDefault(id,Map.of()).entrySet())set(e.getKey(),e.getValue(),false);}
  @Override public boolean restoreMe(){return true;}
  @Override public boolean saveNow(){saves++;if(fail)return false;Map<String,String> values=new HashMap<>();getSet().forEach((k,v)->values.put(k,String.valueOf(v)));DISK.put(character,values);clearChangeTracking();compareAndSetChanges(true,false);return true;}
 }
 static void check(boolean x,String why){checks++;if(!x)throw new AssertionError(why);}
 static void put(Object object,Class<?> owner,String name,Object value)throws Exception{Field f=owner.getDeclaredField(name);f.setAccessible(true);f.set(object,value);}
 static Object get(Object object,Class<?> owner,String name)throws Exception{Field f=owner.getDeclaredField(name);f.setAccessible(true);return f.get(object);}
 public static void broadcast(Player p){ACTORS.get(p).broadcasts++;}public static void refresh(Player p){ACTORS.get(p).weightRefresh++;}
 public static void invisible(Player p,boolean value){try{put(p,WorldObject.class,"_isInvisible",value);ACTORS.get(p).invisibleChanges++;}catch(Exception e){throw new RuntimeException(e);}}
 static void flags(Player p)throws Exception{int flags=0;for(BuffInfo info:p.getEffectList().getEffects())if(info.isInUse())for(AbstractEffect effect:info.getEffects())flags|=effect.getEffectFlags();put(p.getEffectList(),EffectList.class,"_effectFlags",flags);}
 public static void remove(Player p,SkillFinishType type,int id){try{Actor actor=ACTORS.get(p);actor.removed.add(id);p.getEffectList().getBuffs().removeIf(info->info.getSkill().getId()==id);flags(p);}catch(Exception e){throw new RuntimeException(e);}}
 static void makeType()throws Exception{
  ClassDesc parent=Player.class.describeConstable().orElseThrow(),host=PlayingGmStateCheck.class.describeConstable().orElseThrow();
  actorType=MethodHandles.lookup().defineClass(ClassFile.of().build(ClassDesc.of("org.l2jmobius.gameserver.managers.PlayingGmFixturePlayer"),b->{b.withFlags(0x31);b.withSuperclass(parent);
   b.withMethodBody("broadcastUserInfo",MethodTypeDesc.of(CD_void),1,c->c.aload(0).invokestatic(host,"broadcast",MethodTypeDesc.of(CD_void,parent)).return_());
   b.withMethodBody("refreshOverloaded",MethodTypeDesc.of(CD_void),1,c->c.aload(0).invokestatic(host,"refresh",MethodTypeDesc.of(CD_void,parent)).return_());
   b.withMethodBody("setInvisible",MethodTypeDesc.of(CD_void,CD_boolean),1,c->c.aload(0).iload(1).invokestatic(host,"invisible",MethodTypeDesc.of(CD_void,parent,CD_boolean)).return_());
   b.withMethodBody("stopSkillEffects",MethodTypeDesc.of(CD_void,SkillFinishType.class.describeConstable().orElseThrow(),CD_int),1,c->c.aload(0).aload(1).iload(2).invokestatic(host,"remove",MethodTypeDesc.of(CD_void,parent,SkillFinishType.class.describeConstable().orElseThrow(),CD_int)).return_());
  }));
 }
 @SuppressWarnings({"unchecked","rawtypes"})static Player player(int id,boolean gm)throws Exception{
  Player p=(Player)u.allocateInstance(actorType);Actor a=new Actor();a.variables=new ControlledVariables(id);ACTORS.put(p,a);put(p,WorldObject.class,"_objectId",id);put(p,WorldObject.class,"_name","Fixture"+id);put(p,WorldObject.class,"_location",new Location(0,0,0));Field kind=WorldObject.class.getDeclaredField("_instanceType");kind.setAccessible(true);kind.set(p,Enum.valueOf((Class)kind.getType(),"Player"));
  StatSet settings=new StatSet();settings.set("level",gm?70:0);settings.set("name",gm?"Admin":"Player");settings.set("isGM",gm);settings.set("allowAltg",gm);settings.set("allowPeaceAttack",gm);settings.set("giveDamage",!gm);settings.set("takeAggro",!gm);settings.set("gainExp",!gm);settings.set("allowTransaction",!gm);AccessLevel access=new AccessLevel(settings);put(p,Player.class,"_accessLevel",access);put(p,WorldObject.class,"_scripts",new HashMap<>(Map.of(PlayerVariables.class.getName(),a.variables)));put(p,Creature.class,"_effectList",new EffectList(p));return p;
 }
 static Player player(boolean gm)throws Exception{return player(nextId++,gm);}
 static void buff(Player p,Skill skill)throws Exception{BuffInfo info=(BuffInfo)u.allocateInstance(BuffInfo.class);put(info,BuffInfo.class,"_skill",skill);put(info,BuffInfo.class,"_isInUse",true);List<AbstractEffect> list=new ArrayList<>();for(var scope:List.of(EffectScope.GENERAL,EffectScope.SELF)){var effects=skill.getEffects(scope);if(effects!=null)list.addAll(effects);}put(info,BuffInfo.class,"_effects",list);p.getEffectList().getBuffs().add(info);flags(p);}
 static void rawFlags(Player p)throws Exception{p.setInvul(true);p.setDietMode(true);p.setInvisible(true);Actor a=ACTORS.get(p);a.broadcasts=a.weightRefresh=a.invisibleChanges=0;}
 static void role(Player p,AccessLevel before,int level)throws Exception{check(p.getAccessLevel()==before&&p.getAccessLevel().getLevel()==level&&p.isGM()==before.isGm(),"actual raw GM/ACL identity unchanged");check(p.getAccessLevel().allowAltG()==(level==70),"actual Alt+G staff permission retained");}
 static class Selected extends DocumentSkill {final Set<Integer> ids;Selected(File file,Set<Integer> ids){super(file);this.ids=ids;}protected void parseDocument(Document d){var nodes=d.getElementsByTagName("skill");for(int i=nodes.getLength()-1;i>=0;i--){Element e=(Element)nodes.item(i);if(!ids.contains(Integer.parseInt(e.getAttribute("id"))))e.getParentNode().removeChild(e);}super.parseDocument(d);}}
 static List<Skill> skills(String name,int id)throws Exception{Selected doc=new Selected(Path.of("data/stats/skills/"+name).toFile(),Set.of(id));check(doc.parse()!=null,"Native skill XML parsed "+id);return doc.getSkills();}
 static void policy()throws Exception{
  Player gm=player(true),normal=player(false);check(gm.isGM()&&gm.isPlayer()&&gm.asPlayer()==gm,"actual Native GM role and actor type");check(!normal.isGM(),"actual Native ordinary role");check(PlayingGmPolicy.isEnabled()==enabled,"real config enabled/default loading");check(PlayingGmPolicy.isPlaying(gm)==(enabled&&defaultMode),"missing per-character value uses configured default");check(!PlayingGmPolicy.isPlaying(normal),"ordinary actor never playingGM");
  ACTORS.get(gm).variables.set(PlayingGmPolicy.MODE_VARIABLE,true);ACTORS.get(normal).variables.set(PlayingGmPolicy.MODE_VARIABLE,true);check(PlayingGmPolicy.isPlaying(gm)==enabled&&!PlayingGmPolicy.isPlaying(normal),"per-character on still requires real GM role");check(PlayingGmPolicy.hasGameplayBypass(gm)==!enabled&&!PlayingGmPolicy.hasGameplayBypass(normal),"gameplay bypass respects mode/global switch");for(boolean permission:List.of(false,true)){check(PlayingGmPolicy.allowsPrivilege(normal,permission)==permission,"ordinary native ACL preserved");check(PlayingGmPolicy.allowsPrivilege(gm,permission)==(permission&&!enabled),"playing only removes positive privilege");}
  check(PlayingGmPolicy.canTakeAggro(gm)==enabled&&PlayingGmPolicy.canGainExp(gm)==enabled&&PlayingGmPolicy.canTrade(gm)==enabled,"playing mode removes negative staff restrictions; global off preserves them");check(!gm.getAccessLevel().canTakeAggro()&&!gm.getAccessLevel().canGainExp()&&!gm.getAccessLevel().allowTransaction(),"raw negative staff ACL not rewritten");
  put(normal.getAccessLevel(),AccessLevel.class,"_takeAggro",false);put(normal.getAccessLevel(),AccessLevel.class,"_gainExp",false);put(normal.getAccessLevel(),AccessLevel.class,"_allowTransaction",false);check(!PlayingGmPolicy.canTakeAggro(normal)&&!PlayingGmPolicy.canGainExp(normal)&&!PlayingGmPolicy.canTrade(normal),"ordinary custom negative ACL preserved even with stored mode=true");
  put(gm.getAccessLevel(),AccessLevel.class,"_giveDamage",false);put(normal.getAccessLevel(),AccessLevel.class,"_giveDamage",false);check(PlayingGmPolicy.canGiveDamage(gm)==enabled&&!PlayingGmPolicy.canGiveDamage(normal),"Lethal permission: playing GM uses normal damage; ordinary ACL preserved");
  ACTORS.get(gm).variables.set(PlayingGmPolicy.MODE_VARIABLE,false);check(!PlayingGmPolicy.isPlaying(gm)&&PlayingGmPolicy.hasGameplayBypass(gm),"per-character off restores staff bypass");for(boolean permission:List.of(false,true))check(PlayingGmPolicy.allowsPrivilege(gm,permission)==permission,"nonplaying GM native ACL preserved");check(!PlayingGmPolicy.isPlaying(null)&&!PlayingGmPolicy.hasGameplayBypass(null),"null policy false");
  check(!PlayingGmPolicy.canTakeAggro(gm)&&!PlayingGmPolicy.canGainExp(gm)&&!PlayingGmPolicy.canTrade(gm),"nonplaying GM actual negative ACL preserved");
  check(!PlayingGmPolicy.canGiveDamage(gm),"full GM negative damage ACL restored");
  check(PlayingGmState.change(normal,true)==PlayingGmState.ChangeResult.NOT_GM&&PlayingGmState.change(null,true)==PlayingGmState.ChangeResult.NOT_GM,"ordinary/null cannot mutate mode");
 }
 static void enabledState()throws Exception{
  Player a=player(true),b=player(true);ControlledVariables vars=ACTORS.get(a).variables;AccessLevel access=a.getAccessLevel();ControlledVariables other=ACTORS.get(b).variables;other.set(PlayingGmPolicy.MODE_VARIABLE,false);other.saveNow();
  rawFlags(a);buff(a,gmSkill);buff(a,ordinary);check(PlayingGmState.change(a,true)==PlayingGmState.ChangeResult.CHANGED,"real State change accepts persisted on");check(vars.saves==1&&PlayingGmPolicy.isPlaying(a)&&!PlayingGmPolicy.isPlaying(b),"only addressed character switched and saved");check(!a.isInvulSet()&&!a.isInvul()&&!a.getDietMode()&&!a.isInvisible(),"raw invul/diet/invisible normalized");check(ACTORS.get(a).removed.equals(Set.of(gmSkill.getId()))&&a.getEffectList().getEffects().stream().anyMatch(x->x.getSkill()==ordinary),"only genuine Native GM skill removed");check(ACTORS.get(a).broadcasts==1&&ACTORS.get(a).weightRefresh==1,"state emits bounded refresh terminals");role(a,access,70);
  Player relog=player(a.getObjectId(),true);check(PlayingGmPolicy.isPlaying(relog),"fresh actor reloads per-character persisted mode");rawFlags(relog);PlayingGmState.normalize(relog);check(!relog.isInvulSet()&&!relog.getDietMode()&&!relog.isInvisible(),"login normalize respects restored variable");
  check(PlayingGmState.change(a,false)==PlayingGmState.ChangeResult.CHANGED&&!PlayingGmPolicy.isPlaying(a),"mode off persisted");check(!a.isInvulSet()&&!a.getDietMode()&&!a.isInvisible()&&a.getEffectList().getEffects().stream().noneMatch(x->x.getSkill().isGMSkill()),"off never reenables god flags or GM buff");role(a,access,70);check(!PlayingGmPolicy.isPlaying(player(a.getObjectId(),true)),"off survives controlled relog");
  for(boolean existed:List.of(false,true)){Player p=player(true);ControlledVariables v=ACTORS.get(p).variables;if(existed){v.set(PlayingGmPolicy.MODE_VARIABLE,"false");v.saveNow();}Map<String,String> disk=new HashMap<>(DISK.getOrDefault(p.getObjectId(),Map.of()));v.fail=true;rawFlags(p);buff(p,gmSkill);check(PlayingGmState.change(p,true)==PlayingGmState.ChangeResult.SAVE_FAILED,"save failure reported "+existed);check(v.hasVariable(PlayingGmPolicy.MODE_VARIABLE)==existed&&(!existed||v.getString(PlayingGmPolicy.MODE_VARIABLE).equals("false")),"memory value/presence rollback "+existed);check(DISK.getOrDefault(p.getObjectId(),Map.of()).equals(disk),"controlled failed store not persisted "+existed);check(p.isInvulSet()&&p.getDietMode()&&p.isInvisible()&&ACTORS.get(p).removed.isEmpty()&&ACTORS.get(p).broadcasts==0,"failed save has no gameplay mutation/packet "+existed);}
  Player legal=player(true);ACTORS.get(legal).variables.set(PlayingGmPolicy.MODE_VARIABLE,true);rawFlags(legal);buff(legal,gmSkill);buff(legal,ordinary);buff(legal,hide);buff(legal,invul);check(legal.isInvul()&&legal.isInvisible(),"Native ordinary INVUL/Hide present before cleanup");PlayingGmState.normalize(legal);check(!legal.isInvulSet()&&legal.isInvul(),"raw god flag removed but real EffectFlag.INVUL remains effective");check(legal.isInvisible()&&legal.getEffectList().getEffects().stream().anyMatch(x->x.getSkill()==hide),"legitimate Native Hide and its invisible bit retained");check(legal.getEffectList().getEffects().stream().anyMatch(x->x.getSkill()==invul)&&legal.getEffectList().getEffects().stream().anyMatch(x->x.getSkill()==ordinary)&&ACTORS.get(legal).removed.equals(Set.of(gmSkill.getId())),"ordinary class invul/buff not removed");
  Player observer=player(true);ACTORS.get(observer).variables.set(PlayingGmPolicy.MODE_VARIABLE,true);rawFlags(observer);buff(observer,gmSkill);put(observer,Player.class,"_observerMode",true);ControlledVariables ov=ACTORS.get(observer).variables;check(observer.inObserverMode(),"actual Native observer getter true");check(PlayingGmState.change(observer,false)==PlayingGmState.ChangeResult.OBSERVER&&ov.saves==0,"observer switch rejected before persistence");PlayingGmState.normalize(observer);check(observer.inObserverMode()&&observer.isInvulSet()&&observer.getDietMode()&&observer.isInvisible()&&ACTORS.get(observer).removed.isEmpty()&&ACTORS.get(observer).weightRefresh==0&&ACTORS.get(observer).broadcasts==0,"observer state remains untouched");
 }
 static void disabledState()throws Exception{Player p=player(true);var vars=ACTORS.get(p).variables;vars.set(PlayingGmPolicy.MODE_VARIABLE,true);rawFlags(p);buff(p,gmSkill);check(PlayingGmState.change(p,true)==PlayingGmState.ChangeResult.DISABLED,"global off rejects persistence");PlayingGmState.normalize(p);check(vars.saves==0&&p.isInvulSet()&&p.getDietMode()&&p.isInvisible()&&ACTORS.get(p).removed.isEmpty(),"global off leaves normal staff state unchanged");}
 public static void main(String[] args)throws Exception{try{enabled=Boolean.parseBoolean(args[0]);defaultMode=Boolean.parseBoolean(args[1]);Field f=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");f.setAccessible(true);u=(sun.misc.Unsafe)f.get(null);makeType();for(String name:List.of("Buff","Hide","Invincible"))EffectHandler.getInstance().registerHandler((Class)Class.forName("handlers.skill.effects."+name));gmSkill=skills("07000-07099.xml",7029).stream().filter(Skill::isGMSkill).findFirst().orElseThrow();hide=skills("00900-00999.xml",922).getFirst();invul=skills("01400-01499.xml",1418).getFirst();ordinary=skills("01000-01099.xml",1086).getFirst();check(gmSkill.isGMSkill()&&!hide.isGMSkill()&&!invul.isGMSkill()&&!ordinary.isGMSkill(),"Native skill-tree GM metadata distinct from class buffs");policy();if(enabled)enabledState();else disabledState();System.out.println("PLAYING_GM_STATE_CHECK_OK enabled="+enabled+" default="+defaultMode+" checks="+checks+" actualPolicyState/NativeGM/ACL/variables/rawflags/effectflags; store/packets/effect-removal terminals controlled; no World/SQL/client");System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
